function CastingLadleLiningTrowelMaker.init() CastingLadleLiningTrowelMaker.ironStock=14; CastingLadleLiningTrowelMaker.bronzeStock=12; CastingLadleLiningTrowelMaker.woodStock=14; CastingLadleLiningTrowelMaker.leatherStock=8; CastingLadleLiningTrowelMaker.silverStock=8; CastingLadleLiningTrowelMaker.goldStock=6; CastingLadleLiningTrowelMaker.jewelStock=4; CastingLadleLiningTrowelMaker.pearlStock=4; CastingLadleLiningTrowelMaker.productStock={}; CastingLadleLiningTrowelMaker.buildings={}; CastingLadleLiningTrowelMaker.maker=nil; CastingLadleLiningTrowelMaker.activeMaking={}; CastingLadleLiningTrowelMaker.totalProducts=0; CastingLadleLiningTrowelMaker.dayTimer=0; print("[CastingLadleLiningTrowelMaker] Royal Casting Ladle Lining Trowel Maker System initialized (6 products, 4 buildings)") end
function CastingLadleLiningTrowelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CastingLadleLiningTrowelMaker.maker={name=n or ("Lopatar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatar najet: %s (spretnost: %d)",CastingLadleLiningTrowelMaker.maker.name,s),"success") end; return true end
function CastingLadleLiningTrowelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CastingLadleLiningTrowelMaker.build(id) local ok,e=CastingLadleLiningTrowelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CastingLadleLiningTrowelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
