function CastingLadleLiningTrowelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CastingLadleLiningTrowelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CastingLadleLiningTrowelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CastingLadleLiningTrowelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CastingLadleLiningTrowelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CastingLadleLiningTrowelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CastingLadleLiningTrowelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CastingLadleLiningTrowelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CastingLadleLiningTrowelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CastingLadleLiningTrowelMaker.buildings==0 then return false,"Potrebna lopatna delavnica" end; if not CastingLadleLiningTrowelMaker.maker then return false,"Potreben lopatar" end; return true end
function CastingLadleLiningTrowelMaker.make(pt,qty) qty=qty or 1; local ok,e=CastingLadleLiningTrowelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CastingLadleLiningTrowelMaker.ironStock=CastingLadleLiningTrowelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CastingLadleLiningTrowelMaker.bronzeStock=CastingLadleLiningTrowelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CastingLadleLiningTrowelMaker.woodStock=CastingLadleLiningTrowelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CastingLadleLiningTrowelMaker.leatherStock=CastingLadleLiningTrowelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CastingLadleLiningTrowelMaker.silverStock=CastingLadleLiningTrowelMaker.silverStock-d.silverCost*qty end; if d.goldCost then CastingLadleLiningTrowelMaker.goldStock=CastingLadleLiningTrowelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CastingLadleLiningTrowelMaker.jewelStock=CastingLadleLiningTrowelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CastingLadleLiningTrowelMaker.pearlStock=CastingLadleLiningTrowelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CastingLadleLiningTrowelMaker.maker then t=math.max(1,t-math.floor(CastingLadleLiningTrowelMaker.maker.skill/13)) end; table.insert(CastingLadleLiningTrowelMaker.activeMaking,{id="castingladleliningtrowel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CastingLadleLiningTrowelMaker.completeMaking(m) local q=1.0+(CastingLadleLiningTrowelMaker.getQualityBonus()/100); if CastingLadleLiningTrowelMaker.maker then q=q+(CastingLadleLiningTrowelMaker.maker.skill/140) end; q=math.min(2.5,q); CastingLadleLiningTrowelMaker.productStock[m.productType]=(CastingLadleLiningTrowelMaker.productStock[m.productType] or 0)+m.quantity; CastingLadleLiningTrowelMaker.totalProducts=CastingLadleLiningTrowelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CastingLadleLiningTrowelMaker.maker then CastingLadleLiningTrowelMaker.maker.itemsMade=CastingLadleLiningTrowelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CastingLadleLiningTrowelMaker.maker.skill=math.min(100,CastingLadleLiningTrowelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"castingladleliningtrowel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CastingLadleLiningTrowelMaker.update(dt) if not _G.state then return end; CastingLadleLiningTrowelMaker.dayTimer=CastingLadleLiningTrowelMaker.dayTimer+dt; if CastingLadleLiningTrowelMaker.dayTimer>=30 then CastingLadleLiningTrowelMaker.dayTimer=0; for i=#CastingLadleLiningTrowelMaker.activeMaking,1,-1 do local m=CastingLadleLiningTrowelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CastingLadleLiningTrowelMaker.completeMaking(m); table.remove(CastingLadleLiningTrowelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CastingLadleLiningTrowelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CastingLadleLiningTrowelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
